{'code': "from qgis.gui import QgsVertexMarker, QgsRubberBand
c = iface.mapCanvas()
res = []
for it in c.items():
    if not it.isVisible():
        continue
    cls = type(it).__name__
    if cls in ('QgsSnapToGridCanvasItem','QgsAdvancedDigitizingCanvasItem','QGraphicsItem'):
        continue
    entry = {'class': cls}
    if isinstance(it, QgsVertexMarker):
        ctr = it.center()
        entry['pos'] = (round(ctr.x(),6), round(ctr.y(),6))
    elif isinstance(it, QgsRubberBand):
        entry['nVertices'] = it.numberOfVertices()
        entry['pts'] = []
        try:
            geom = it.asGeometry()
            entry['wkt'] = geom.asWkt()[:200]
        except Exception:
            pass
    res.append(entry)
result = res"}

